import React, { useState, useEffect, useRef } from 'react';

// ── Dates ───────────────────────────────────────────────────────────────
// The 26th is our day: 3rd was May 26, 7th was Sept 26 → we started Feb 26.
const WE_MET_ON = new Date('2026-02-26T00:00:00');
const FLIGHT_DATE = new Date('2026-11-14T00:00:00');

const DAY_MS = 86400000;

const daysBetween = (from, to) => Math.max(0, Math.floor((to.getTime() - from.getTime()) / DAY_MS));

const fullMonthsBetween = (from, to) => {
  let months = (to.getFullYear() - from.getFullYear()) * 12 + (to.getMonth() - from.getMonth());
  if (to.getDate() < from.getDate()) months -= 1;
  return Math.max(0, months);
};

const pad = (n) => String(n).padStart(2, '0');

const StillHere = () => {
  const [stage, setStage] = useState('envelope');
  const [now, setNow] = useState(new Date());
  const [isPlaying, setIsPlaying] = useState(false);
  const [songIndex, setSongIndex] = useState(0);
  const audioRef = useRef(null);
  const timerRef = useRef(null);

  const playlist = [
    { title: 'ILYSB', artist: 'LANY', src: 'https://archive.org/download/LANYILYSBlyricVideo/LANY%20-%20ILYSB%20%28lyric%20video%29.mp3' },
    { title: 'River Flows In You', artist: 'Yiruma', src: "https://archive.org/download/yiruma-frame-2017/Yiruma%20-%20Frame%20(2017)/11.%20River%20Flows%20In%20You%20('%20r%20a%20m%20e'%20Ver.).mp3" },
  ];

  // Live counter
  const totalDays = daysBetween(WE_MET_ON, now);
  const monthsTogether = fullMonthsBetween(WE_MET_ON, now);
  // Days elapsed since the most recent monthly anniversary (the 26th).
  const annivThisMonth = new Date(now.getFullYear(), now.getMonth(), WE_MET_ON.getDate());
  const lastAnniversary = now >= annivThisMonth
    ? annivThisMonth
    : new Date(now.getFullYear(), now.getMonth() - 1, WE_MET_ON.getDate());
  const daysIntoMonth = daysBetween(lastAnniversary, now);

  const elapsed = Math.max(0, now.getTime() - WE_MET_ON.getTime());
  const hours = Math.floor(elapsed / 3600000) % 24;
  const minutes = Math.floor(elapsed / 60000) % 60;
  const seconds = Math.floor(elapsed / 1000) % 60;

  const flightDiff = FLIGHT_DATE.getTime() - now.getTime();
  const flightLanded = flightDiff <= 0;
  const daysToFlight = Math.max(0, Math.ceil(flightDiff / DAY_MS));

  useEffect(() => {
    const tick = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(tick);
  }, []);

  useEffect(() => {
    if (!document.getElementById('mimi-still-here-fonts')) {
      const link = document.createElement('link');
      link.id = 'mimi-still-here-fonts';
      link.href = 'https://fonts.googleapis.com/css2?family=Caveat:wght@400;600;700&family=Lora:ital,wght@0,400;0,600;1,400&family=Cormorant+Garamond:wght@500;600;700&family=Special+Elite&display=swap';
      link.rel = 'stylesheet';
      document.head.appendChild(link);
    }
    return () => {
      if (timerRef.current) window.clearTimeout(timerRef.current);
    };
  }, []);

  useEffect(() => {
    if (stage === 'letter' && audioRef.current) {
      audioRef.current.src = playlist[songIndex].src;
      const p = audioRef.current.play();
      if (p !== undefined) {
        p.then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stage, songIndex]);

  const handleOpenLetter = () => {
    setStage('opening');
    timerRef.current = window.setTimeout(() => setStage('letter'), 1200);
  };

  const handleBackToEnvelope = () => {
    if (timerRef.current) window.clearTimeout(timerRef.current);
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    setIsPlaying(false);
    setSongIndex(0);
    setStage('opening');
    window.setTimeout(() => setStage('envelope'), 800);
  };

  const handleNextSong = () => {
    setSongIndex((prev) => (prev + 1) % playlist.length);
  };

  const ENV_W = 300;
  const ENV_H = 195;

  return (
    <div style={styles.page}>

      {/* ── ENVELOPE STAGE ── */}
      {(stage === 'envelope' || stage === 'opening') && (
        <div style={styles.envelopeWrapper}>
          <p style={styles.preLabel}>Written the morning after</p>

          <div style={{ width: `${ENV_W}px`, height: `${ENV_H}px`, position: 'relative', filter: 'drop-shadow(0 12px 30px rgba(0,0,0,0.22))' }}>
            {/* Back */}
            <div style={{ position: 'absolute', inset: 0, background: '#e8d5b7', borderRadius: '4px' }} />

            {/* Top flap */}
            <div style={{
              position: 'absolute', top: 0, left: 0, width: 0, height: 0,
              borderLeft: `${ENV_W / 2}px solid transparent`,
              borderRight: `${ENV_W / 2}px solid transparent`,
              borderTop: `${ENV_H * 0.48}px solid #c9a97a`,
              transformOrigin: 'top center', zIndex: 4,
              transition: 'transform 0.9s cubic-bezier(0.4, 0, 0.2, 1)',
              transform: stage === 'opening' ? 'rotateX(-180deg)' : 'rotateX(0deg)',
            }} />

            {/* Side triangles */}
            <div style={{ position: 'absolute', bottom: 0, left: 0, width: 0, height: 0, borderBottom: `${ENV_H}px solid #dfc9a8`, borderRight: `${ENV_W / 2}px solid transparent`, zIndex: 2 }} />
            <div style={{ position: 'absolute', bottom: 0, right: 0, width: 0, height: 0, borderBottom: `${ENV_H}px solid #c8b08a`, borderLeft: `${ENV_W / 2}px solid transparent`, zIndex: 2 }} />
            <div style={{ position: 'absolute', bottom: 0, left: 0, width: 0, height: 0, borderBottom: `${ENV_H * 0.55}px solid #e2c99e`, borderLeft: `${ENV_W / 2}px solid transparent`, borderRight: `${ENV_W / 2}px solid transparent`, zIndex: 2 }} />

            {/* Front face */}
            <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', zIndex: 3, paddingBottom: '10px' }}>
              {/* Stamp — top right */}
              <div style={{
                position: 'absolute', top: '12px', right: '14px',
                width: '42px', height: '52px',
                border: '2px solid rgba(100,70,30,0.45)',
                borderRadius: '2px',
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                background: 'rgba(255,255,255,0.55)',
                gap: '2px',
              }}>
                <span style={{ fontSize: '17px', lineHeight: 1 }}>♥</span>
                <span style={{ fontFamily: "'Caveat', cursive", fontSize: '8px', color: '#6b3a1f', letterSpacing: '0.5px' }}>14 NOV</span>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginBottom: '10px', alignItems: 'flex-start', width: '130px' }}>
                <div style={{ height: '1.5px', width: '65px', background: 'rgba(100,70,30,0.25)', borderRadius: '2px' }} />
                <div style={{ height: '1.5px', width: '130px', background: 'rgba(100,70,30,0.25)', borderRadius: '2px' }} />
              </div>
              <p style={{ fontFamily: "'Caveat', cursive", fontSize: '14px', color: 'rgba(80,50,20,0.55)', marginBottom: '12px', marginTop: 0 }}>
                For: <span style={{ fontSize: '24px', color: '#6b3a1f', fontWeight: 700 }}>Mimi</span>
              </p>
              {/* Wax seal */}
              <div style={{
                width: '46px', height: '46px', background: '#b71c1c', borderRadius: '50%',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                boxShadow: '0 2px 8px rgba(183,28,28,0.5)',
                border: '2px solid rgba(255,255,255,0.3)',
                animation: 'pulseSeal 2.5s ease-in-out infinite',
              }}>
                <span style={{ fontSize: '20px', color: 'white', lineHeight: 1 }}>♥</span>
              </div>
            </div>
          </div>

          {stage === 'envelope' && (
            <>
              <button className="mimi-open-btn" style={styles.openBtn} onClick={handleOpenLetter}>
                Open the letter  ↑
              </button>
              <p style={styles.countdownPeek}>Day {totalDays} — still counting.</p>
            </>
          )}
          {stage === 'opening' && (
            <p style={styles.openingText}>Opening...</p>
          )}
        </div>
      )}

      {/* ── LETTER STAGE ── */}
      {stage === 'letter' && (
        <div style={styles.letterWrapper}>
          <div style={styles.letterPage}>
            {/* Red margin line */}
            <div style={styles.marginLine} />

            <div className="mimi-letter-content" style={styles.letterContent}>
              <div style={{...styles.letterMetaRow, animation: 'readyRise 0.5s ease-out both', animationDelay: '0s'}}>
                <span style={styles.privateTag}>Private note</span>
                <span style={styles.dateText}>October 8, 2026</span>
              </div>

              <p style={{...styles.salutation, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.08s'}}>Dear Mimi,</p>

              {/* ── DAYS SINCE WE MET ── */}
              <div style={{...styles.counterCard, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.16s'}}>
                <p style={styles.counterLabel}>Days since we met</p>
                <p style={styles.counterNumber}>{totalDays}</p>
                <p style={styles.counterSub}>
                  {monthsTogether} months and {daysIntoMonth} days — since February 26, 2026
                </p>
                <div style={styles.counterTicker}>
                  <span>{pad(hours)}</span><span style={styles.tickColon}>:</span>
                  <span>{pad(minutes)}</span><span style={styles.tickColon}>:</span>
                  <span>{pad(seconds)}</span>
                  <span style={styles.counterTickerLabel}>today, and still counting</span>
                </div>
              </div>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.26s'}}>
                We fought last night. I&apos;m not going to write around it, and I&apos;m not going to explain it away either. So here it is, plainly.
              </p>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.34s'}}>
                I&apos;m sorry. Not the easy kind of sorry that comes with an excuse attached — the real one. You didn&apos;t deserve how I talked to you, and I&apos;ve been sitting with that all morning.
              </p>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.42s'}}>
                That counter above is the part nobody can argue with. {totalDays} days and climbing. Whatever happened last night, it doesn&apos;t touch that number — and I&apos;m not letting it.
              </p>

              <div style={{...styles.highlightBox, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.52s'}}>
                <p style={styles.highlightText}>
                  Being right is worth nothing to me. You are worth everything.
                </p>
              </div>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.62s'}}>
                I&apos;m not asking you to be okay tonight. I&apos;m asking for one call — just one, whenever you feel like it. We can talk about last night, or we can talk about nothing at all. Either one counts.
              </p>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.7s'}}>
                And on the 14th I land in Davao. I booked it because I want to see you — that&apos;s the whole reason.
              </p>

              {/* ── BOARDING PASS ── */}
              <div style={{...styles.passCard, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.8s'}}>
                <div style={styles.passMain}>
                  <p style={styles.passLabel}>Flight</p>
                  <p style={styles.passRoute}>
                    <span style={styles.passCode}>IDN</span>
                    <span style={styles.passArrow}>→</span>
                    <span style={styles.passCode}>DVO</span>
                  </p>
                  <p style={styles.passPlace}>Davao, Philippines</p>
                </div>
                <div style={styles.passStub}>
                  <p style={styles.passLabel}>Date</p>
                  <p style={styles.passDate}>14 NOV</p>
                  <p style={styles.passCountdown}>
                    {flightLanded ? 'Landed ♥' : `in ${daysToFlight} day${daysToFlight === 1 ? '' : 's'}`}
                  </p>
                  <p style={styles.passStatus}>Booked</p>
                </div>
              </div>

              <p style={{...styles.para, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.88s'}}>
                You don&apos;t have to answer tonight. I&apos;ll still be on the other end tomorrow, and the day after that.
              </p>

              <div style={{...styles.signatureArea, animation: 'readyRise 0.5s ease-out both', animationDelay: '0.98s'}}>
                <p style={styles.signatureLine}>Still yours,</p>
                <p style={styles.signatureName}>Gagas</p>
                <p style={styles.signatureHint}>(No pressure. Take all the time you need. ♥)</p>
              </div>

              <p style={{...styles.letterFooter, animation: 'readyRise 0.5s ease-out both', animationDelay: '1.06s'}}>
                Day {totalDays}. Still counting.
              </p>

              <div style={{ textAlign: 'center', marginTop: '32px', animation: 'readyRise 0.5s ease-out both', animationDelay: '1.12s' }}>
                <button className="mimi-fold-btn" style={styles.foldBackBtn} onClick={handleBackToEnvelope}>
                  ↩ Back to envelope
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── MUSIC PLAYER ── */}
      {stage === 'letter' && (
        <div style={styles.musicPlayer}>
          <audio
            ref={audioRef}
            src={playlist[songIndex].src}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            onEnded={handleNextSong}
          />
          <span style={{ ...styles.musicNote, animationPlayState: isPlaying ? 'running' : 'paused' }}>♪</span>
          <div style={styles.musicInfo}>
            <span style={styles.musicTitle}>{playlist[songIndex].title}</span>
            <span style={styles.musicArtist}>{playlist[songIndex].artist}</span>
          </div>
          <button
            style={styles.musicBtn}
            onClick={() => {
              if (!audioRef.current) return;
              if (isPlaying) {
                audioRef.current.pause();
              } else {
                audioRef.current.play().catch(() => {});
              }
            }}
          >
            {isPlaying ? '⏸' : '▶'}
          </button>
          <button
            style={{...styles.musicBtn, fontSize: '11px'}}
            onClick={handleNextSong}
            title="Next song"
          >
            ⏭
          </button>
        </div>
      )}

      <style>{`
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(40px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes floatBtn {
          0%, 100% { transform: translateY(0px); }
          50%       { transform: translateY(-5px); }
        }
        @keyframes pulseSeal {
          0%, 100% { transform: scale(1); }
          50%       { transform: scale(1.07); }
        }
        @keyframes noteBounce {
          0%, 100% { transform: translateY(0px) rotate(-8deg); }
          50%       { transform: translateY(-4px) rotate(8deg); }
        }
        @keyframes readyRise {
          from { transform: translateY(12px); opacity: 0; }
          to   { transform: translateY(0);    opacity: 1; }
        }
        @keyframes softPulse {
          0%, 100% { opacity: 0.55; }
          50%       { opacity: 0.9; }
        }

        .mimi-open-btn {
          transition: background 0.2s ease, color 0.2s ease, transform 0.18s ease, box-shadow 0.18s ease !important;
        }
        .mimi-open-btn:hover {
          background: rgba(107, 58, 31, 0.08) !important;
          transform: translateY(-2px) !important;
          box-shadow: 0 8px 24px rgba(107, 58, 31, 0.18) !important;
          animation-play-state: paused !important;
        }

        .mimi-fold-btn {
          transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease !important;
        }
        .mimi-fold-btn:hover {
          background: rgba(107, 58, 31, 0.06) !important;
          border-color: rgba(107, 58, 31, 0.55) !important;
          color: rgba(107, 58, 31, 0.85) !important;
        }

        @media (max-width: 640px) {
          .mimi-letter-content {
            padding: 0 14px 0 22px !important;
          }
          .mimi-open-btn {
            padding: 12px 32px !important;
            font-size: 16px !important;
          }
        }

        @media (max-width: 360px) {
          .mimi-letter-content {
            padding: 0 10px 0 16px !important;
          }
        }
      `}</style>
    </div>
  );
};

